css:
/* WI-002399: Arial throughout, per the criteria - declared on the wrapper and on
   every descendant so nothing reintroduces another face.

   The Arabic fallbacks after it are not a hedge. There is no Arial on the print
   server: fontconfig answers "Arial" with Liberation Sans, which is metric-
   compatible with Arial and carries no Arabic glyphs at all - so Arial alone
   renders every Arabic word in this letter as empty boxes. Arial still comes
   first and takes all the Latin text; the Arabic falls through to a face that
   can draw it. Install an Arabic-capable Arial on the server and these can go. */
.pow-letter, .pow-letter * { font-family: Arial, 'Noto Sans Arabic', 'DejaVu Sans', sans-serif; }
.pow-letter { direction: rtl; font-size: 12px; color: #000; }
/* The masthead is a table because the PDF is drawn by wkhtmltopdf, whose WebKit
   predates flexbox: display:flex was ignored and the title dropped onto its own
   line below the logo instead of sitting opposite it. */
.pow-hd { width: 100%; border: none; border-collapse: collapse; direction: ltr; margin: 0 0 14px; }
.pow-hd td { border: none; padding: 0; vertical-align: middle; }
.pow-logo { max-height: 64px; }
.pow-hd-title { text-align: right; font-size: 22px; font-weight: bold; }
.boiler { line-height: 2; margin: 10px 0 18px; }
/* An English run inside an Arabic sentence is one unbreakable piece. Without this
   the contract date broke after "25 / 02 /" and the client name after "Co.", and
   each fragment was laid out at the far side of a line of its own - the scattered
   header the client saw. */
.en { direction: ltr; unicode-bidi: embed; white-space: nowrap; }
/* A table value takes its direction from its own first strong character, so an
   Arabic value reads right-to-left and a Latin one left-to-right, in a table that
   is itself RTL. */
.val { unicode-bidi: plaintext; }
.schedule { margin: 0 0 14px; line-height: 1.9; }
.sched-title { text-align: center; font-weight: bold; margin-bottom: 4px; }
/* No table-layout:fixed and no column percentages: the headings carry nowrap, so
   every column is at least as wide as its own heading and the table shares out what
   is left. Under fixed percentages the Arabic headings shredded into three- and
   four-word fragments, and because no two columns wrapped at the same place the
   days line, the أو and the hours line never lined up across the row. */
.pow-tbl { width: 100%; border-collapse: collapse; direction: rtl; }
.pow-tbl th, .pow-tbl td { border: 1px solid #000; padding: 6px 8px; vertical-align: top; word-wrap: break-word; overflow-wrap: break-word; }
.pow-tbl thead { display: table-row-group; }
.pow-tbl thead th { font-weight: bold; white-space: nowrap; text-align: center; }
.pow-tbl .c-type { text-align: right; }
.pow-tbl .c-contract { text-align: left; }
.pow-tbl .c-worked { text-align: left; }
.pow-tbl .c-breakdown { text-align: right; }
/* The breakdown is twenty near-identical lines, so a line that wraps stands out as
   a ragged half-line among them. Keeping them unbreakable also makes this column the
   one the table sizes to first, which is the intent: it holds the longest text. */
.pow-tbl .c-breakdown .ln { white-space: nowrap; }
.pow-tbl .ln { margin-bottom: 6px; line-height: 1.35; }
.pow-tbl .ln:last-child { margin-bottom: 0; }
/* Centred so the separator reads as one, and not as another line of the figures
   it divides - in the headings and in the rows alike. */
.pow-tbl .or { font-weight: bold; margin: 6px 0; text-align: center; }
/* A heading names one unit or two, so its lines need the same spacing the cells use. */
.pow-tbl .hd-ln { line-height: 1.35; }
.empty { text-align: center; font-style: italic; }
.sign { margin-top: 40px; line-height: 2.2; }
.nm-title { font-weight: bold; margin: 18px 0 6px; }
.nm-tbl { table-layout: fixed; }
.nm-tbl .c-nm-cat { width: 70%; text-align: right; }
.nm-tbl .c-nm-amount { width: 30%; text-align: left; }

.nm-tbl .nm-total td { font-weight: bold; }
@media print { @page { size: A4 portrait; margin: 15mm; } }
